  "Zer vs zein: ¿hay dónde elegir?": "Zer vs zein: is there a choice?", "Zer pregunta por algo que no conoces (zer da hau? → liburua da). Zein pregunta cuál de varios que ya tienes delante (zein da zurea? → hori). Truco: si la respuesta es señalar, es zein.": "Zer asks about something you don't know (zer da hau? → liburua da). Zein asks which of several in front of you (zein da zurea? → hori). Trick: if the answer is pointing, it's zein.",
