  "perro": "dog",
  "¿De quién es este libro?": "Whose book is this?",
  "Es mío.": "It is mine.",
  "¿Eso es tuyo?": "Is that yours?",
  "No, es el libro de Ane.": "No, it is Ane's book.",
  "Es el coche de mamá.": "It is mum's car.",
  "La casa de papá es grande.": "Dad's house is big.",
  "El perro de mi amigo es bonito.": "My friend's dog is pretty.",
  "Esta casa es nuestra.": "This house is ours.",
  "Ese bolso es suyo.": "That bag is hers.",
  "¿Es vuestro?": "Is it yours (plural)?",
  "La bici de Mikel es nueva.": "Mikel's bike is new.",
  "De Ane: -ren / -en": "Ane's: -ren / -en",
  "Tras vocal, -ren: Aneren liburua, amaren autoa. Tras consonante, -en: Mikelen bizikleta, Jonen etxea. Y va DELANTE de la cosa, como «el libro de Ane» al revés.": "After a vowel, -ren: Aneren liburua, amaren autoa. After a consonant, -en: Mikelen bizikleta, Jonen etxea. It goes BEFORE the thing, like “Ane's book” in English.",
  "Mío, tuyo: nirea, zurea": "Mine, yours: nirea, zurea",
  "Solos, con -a: Nirea da (es mío). Delante de un nombre, sin -a: nire liburua (mi libro). Igual zure / zurea, gure / gurea.": "On their own, with -a: Nirea da (it is mine). Before a noun, no -a: nire liburua (my book). Same for zure / zurea, gure / gurea.",
  "Preguntar: norena?": "Asking: norena?",
  "Norena da? = ¿de quién es? Se responde con el dueño + -ren(a): Aneren(a) da, o con nirea / zurea.": "Norena da? = whose is it? Answer with owner + -ren(a): Aneren(a) da, or with nirea / zurea.",
  "¿De quién es este bolso?": "Whose bag is this?",
  "No es mío. Es el bolso de Ane, creo.": "It is not mine. It is Ane's bag, I think.",
  "¿Y estas gafas?": "And these glasses?",
  "¡Esas sí, son mías! Gracias.": "Those yes, they are mine! Thanks.",
  "Hogeita hamar, berrogei… ehun": "Hogeita hamar, berrogei… ehun",
  "Telefonoa eskatzen · pidiendo el teléfono": "Telefonoa eskatzen · asking for a phone number",
  "___ urte ditu": "___ urte ditu",
