  "gose naiz · egarri naiz": "gose naiz · egarri naiz",
  "nekatuta nago": "nekatuta nago",
  "Ahora es un estado: «está tranquilo»": "Now it is a state: “he is calm (right now)”",
  "Ahora son varios": "Now there are several",
  "Añade a Jon (plural)": "Add Jon (plural)",
  "Ahora es sed": "Now it is thirst",
  "De quién: -ren / -en y nirea, zurea…": "Whose: -ren / -en and nirea, zurea…",
  "El dueño lleva -ren (tras vocal) o -en (tras consonante) y va delante de la cosa: Aneren liburua, Mikelen etxea. Los posesivos sueltos llevan -a: nirea, zurea, berea, gurea, zuena, haiena. Delante de un nombre, sin -a: nire liburua.": "The owner takes -ren (after a vowel) or -en (after a consonant) and goes before the thing: Aneren liburua, Mikelen etxea. Stand-alone possessives take -a: nirea, zurea, berea, gurea, zuena, haiena. Before a noun, no -a: nire liburua.",
  "delante del nombre": "before a noun",
