  "Responde: de papá": "Answer: dad's",
  "Números de 20 a 100": "Numbers from 20 to 100",
  "Se cuenta de 20 en 20: hogei, berrogei, hirurogei, laurogei, ehun. Lo que sobra se une con -ta: berrogeita bost (45), hirurogeita hamar (70), laurogeita hemeretzi (99). El nombre va en singular (hogei euro) y el verbo en plural (dira).": "Counting goes in twenties: hogei, berrogei, hirurogei, laurogei, ehun. The remainder is joined with -ta: berrogeita bost (45), hirurogeita hamar (70), laurogeita hemeretzi (99). The noun is singular (hogei euro) and the verb plural (dira).",
