  "Si el verbo lleva objeto (desayuno algo, leo algo) va con dut: gosaltzen dut, irakurtzen dut. Si no (me levanto, voy, vuelvo), con naiz: jaikitzen naiz, joaten naiz, itzultzen naiz.": "If the verb has an object (I eat something, I read something) it goes with dut: gosaltzen dut, irakurtzen dut. If not (I get up, I go, I come back), with naiz: jaikitzen naiz, joaten naiz, itzultzen naiz.",
