  "Cada día, cada semana: -ero": "Every day, every week: -ero",
  "egunero (cada día), astero (cada semana), hilero (cada mes), goizero (cada mañana), gauero (cada noche). Se pega al nombre.": "egunero (every day), astero (every week), hilero (every month), goizero (every morning), gauero (every night). It attaches to the noun.",
  "Una vez, dos veces: behin, bitan, hirutan": "Once, twice: behin, bitan, hirutan",
  "astean behin (una vez a la semana), astean bitan (dos), astean hirutan (tres), hilean behin. Zenbatetan? = ¿cuántas veces?": "astean behin (once a week), astean bitan (twice), astean hirutan (three times), hilean behin. Zenbatetan? = how many times?",
  "Nunca: ez … inoiz": "Never: ez … inoiz",
  "Ez dut inoiz telebista ikusten. El ez va delante del auxiliar e inoiz detrás. Por sí solo, inoiz ez = nunca.": "Ez dut inoiz telebista ikusten. Ez goes before the auxiliary and inoiz after. On its own, inoiz ez = never.",
  "¿Vienes mucho al polideportivo?": "Do you come to the sports centre often?",
  "Tres veces a la semana. ¿Y tú?": "Three times a week. And you?",
  "De vez en cuando. Normalmente voy al monte.": "From time to time. I usually go to the mountains.",
  "¡Yo nunca voy al monte! La próxima, ¿juntos?": "I never go to the mountains! Next time, together?",
  "Joango naiz, egingo dut, ikusiko dut": "Joango naiz, egingo dut, ikusiko dut",
