  "Mañana iré al monte.": "Tomorrow I will go to the mountains.",
  "El fin de semana comeré con amigos.": "At the weekend I will have lunch with friends.",
  "Esta noche veré una película.": "Tonight I will watch a film.",
  "Pasado mañana iremos a Bilbao.": "The day after tomorrow we will go to Bilbao.",
  "La semana que viene tengo examen.": "Next week I have an exam.",
  "En vacaciones estudiaré euskera.": "On holiday I will study Basque.",
  "¿Qué vas a hacer mañana?": "What are you going to do tomorrow?",
  "No sé. Me quedaré en casa.": "I don't know. I will stay at home.",
  "Ane vendrá pronto.": "Ane will come soon.",
  "El año que viene vendré a Donostia.": "Next year I will come to Donostia.",
  "Compraré pan.": "I will buy bread.",
  "Futuro: -ko / -go": "Future: -ko / -go",
  "ikusi → ikusiko dut, erosi → erosiko dut, hartu → hartuko dut, etorri → etorriko naiz. Si el verbo acaba en -n, -go: joan → joango naiz, egin → egingo dut, jan → jango dut.": "ikusi → ikusiko dut, erosi → erosiko dut, hartu → hartuko dut, etorri → etorriko naiz. If the verb ends in -n, -go: joan → joango naiz, egin → egingo dut, jan → jango dut.",
  "naiz o dut, como siempre": "naiz or dut, as always",
  "Con objeto, dut: film bat ikusiko dut. Sin objeto, naiz: mendira joango naiz, etxean geratuko naiz. Nosotros: joango gara / ikusiko dugu.": "With an object, dut: film bat ikusiko dut. Without, naiz: mendira joango naiz, etxean geratuko naiz. We: joango gara / ikusiko dugu.",
  "Cuándo: bihar, asteburuan, datorren astean": "When: bihar, asteburuan, datorren astean",
  "bihar (mañana), etzi (pasado mañana), asteburuan (el finde), datorren astean / urtean (la semana / el año que viene), oporretan (en vacaciones).": "bihar (tomorrow), etzi (the day after tomorrow), asteburuan (at the weekend), datorren astean / urtean (next week / year), oporretan (on holiday).",
  "¿Qué vas a hacer el fin de semana?": "What are you going to do at the weekend?",
  "El sábado iré al monte. Y el domingo, no sé.": "On Saturday I will go to the mountains. And on Sunday, I don't know.",
  "¿El domingo comes con nosotros?": "Will you have lunch with us on Sunday?",
  "¡Sí, muy bien! ¿A qué hora?": "Yes, great! At what time?",
  "A las dos. ¡Pago yo!": "At two. My treat!",
  "Solo la una es singular: ordu bata da. Las demás llevan -ak y dira: hirurak dira.": "Only one o'clock is singular: ordu bata da. The rest take -ak and dira: hirurak dira.",
  "Las horas (menos la una) son plural: -ak + dira. Y media: eta erdi; y cuarto: eta laurden; menos cuarto: laurden gutxi.": "Hours (except one) are plural: -ak + dira. Half past: eta erdi; quarter past: eta laurden; quarter to: laurden gutxi.",
  "laurden gutxi = menos cuarto: bostak laurden gutxi = las cinco menos cuarto (4:45).": "laurden gutxi = quarter to: bostak laurden gutxi = quarter to five (4:45).",
  "¿A qué hora? -etan: zortzietan (a las ocho), ordu batean (a la una), hirurak eta erdietan (a las tres y media).": "At what time? -etan: zortzietan (at eight), ordu batean (at one), hirurak eta erdietan (at half past three).",
  "goizeko / arratsaldeko / gaueko + hora: goizeko zortziak (las ocho de la mañana).": "goizeko / arratsaldeko / gaueko + hour: goizeko zortziak (eight in the morning).",
  "Los días llevan -a: gaur astelehena da. Ayer: atzo igandea zen (zen = era/fue).": "Days take -a: gaur astelehena da. Yesterday: atzo igandea zen (zen = was).",
  "«Los lunes», cada lunes: -etan: astelehenetan, ostiraletan.": "“On Mondays”, every Monday: -etan: astelehenetan, ostiraletan.",
  "Fechas: mes + -aren + día: azaroaren hamazazpia (17 de noviembre). Cuándo: maiatzaren bostean (el 5 de mayo).": "Dates: month + -aren + day: azaroaren hamazazpia (17 November). When: maiatzaren bostean (on 5 May).",
  "Presente habitual sin objeto: -tzen/-ten + naiz: jaikitzen naiz (me levanto), joaten naiz (voy), oheratzen naiz (me acuesto).": "Habitual present without object: -tzen/-ten + naiz: jaikitzen naiz (I get up), joaten naiz (I go), oheratzen naiz (I go to bed).",
  "Presente habitual con objeto: -tzen/-ten + dut: gosaltzen dut (desayuno), irakurtzen dut (leo), kirola egiten dut (hago deporte).": "Habitual present with object: -tzen/-ten + dut: gosaltzen dut (I have breakfast), irakurtzen dut (I read), kirola egiten dut (I do sport).",
  "-ero = cada: egunero (cada día), astero (cada semana), hilero (cada mes), goizero (cada mañana).": "-ero = every: egunero (every day), astero (every week), hilero (every month), goizero (every morning).",
  "astean behin / bitan / hirutan = una / dos / tres veces a la semana. Zenbatetan? = ¿cuántas veces?": "astean behin / bitan / hirutan = once / twice / three times a week. Zenbatetan? = how many times?",
  "Nunca: ez + auxiliar + inoiz: ez dut inoiz telebista ikusten.": "Never: ez + auxiliary + inoiz: ez dut inoiz telebista ikusten.",
  "Futuro: verbo + -ko: ikusiko dut (veré), erosiko dut (compraré), etorriko da (vendrá).": "Future: verb + -ko: ikusiko dut (I will see), erosiko dut (I will buy), etorriko da (he/she will come).",
  "Tras -n el futuro es -go: joan → joango naiz, egin → egingo dut, jan → jango dut.": "After -n the future is -go: joan → joango naiz, egin → egingo dut, jan → jango dut.",
  "datorren = que viene: datorren astean (la semana que viene), datorren urtean (el año que viene).": "datorren = coming, next: datorren astean (next week), datorren urtean (next year).",
  "Las horas: qué hora es y a qué hora": "Hours: what time it is and at what time",
  "Solo la una es singular (ordu bata da); el resto plural con -ak y dira (hirurak dira). Y media: eta erdi; y cuarto: eta laurden; menos cuarto: laurden gutxi; y diez: eta hamar. ¿A qué hora? Zer ordutan? → -etan: zortzietan, ordu batean, hirurak eta erdietan.": "Only one o'clock is singular (ordu bata da); the rest plural with -ak and dira (hirurak dira). Half past: eta erdi; quarter past: eta laurden; quarter to: laurden gutxi; ten past: eta hamar. At what time? Zer ordutan? → -etan: zortzietan, ordu batean, hirurak eta erdietan.",
