  "Me gusta + verbo: el verbo con -t(z)ea: mendira joatea gustatzen zait, irakurtzea gustatzen zait.": "Like + verb: the verb with -t(z)ea: mendira joatea gustatzen zait, irakurtzea gustatzen zait.",
  "Hacer deporte: X egin: korrika egiten dut (corro), igeri egiten dut (nado), kirola egiten dut.": "Doing sport: X egin: korrika egiten dut (I run), igeri egiten dut (I swim), kirola egiten dut.",
  "Jugar a: pilotan / futbolean jokatzen dut (la actividad lleva -n).": "Play: pilotan / futbolean jokatzen dut (the activity takes -n).",
  "Con: -ekin (plural: lagunekin), -rekin tras vocal (familiarekin, Anerekin). Norekin? = ¿con quién?": "With: -ekin (plural: lagunekin), -rekin after a vowel (familiarekin, Anerekin). Norekin? = with whom?",
  "Medio de transporte: -z: trenez (en tren), kotxez (en coche), oinez (a pie).": "Means of transport: -z: trenez (by train), kotxez (by car), oinez (on foot).",
  "A un/una: X batera: kontzertu batera (a un concierto), hondartza batera.": "To a: X batera: kontzertu batera (to a concert), hondartza batera.",
  "ari du = está (ahora mismo): euria ari du (está lloviendo), elurra ari du (está nevando).": "ari du = is (right now): euria ari du (it is raining), elurra ari du (it is snowing).",
  "Hace frío / calor / buen tiempo: egiten du: hotz egiten du, bero egiten du, eguraldi ona egiten du.": "It is cold / hot / good weather: egiten du: hotz egiten du, bero egiten du, eguraldi ona egiten du.",
  "eguzkia dago = hace sol (literalmente «hay sol»); lainotuta dago = está nublado.": "eguzkia dago = it is sunny (literally “there is sun”); lainotuta dago = it is cloudy.",
  "haizea dabil = hace viento (el viento «anda»; dabil = anda, de ibili).": "haizea dabil = it is windy (the wind “walks”; dabil = walks, from ibili).",
  "Futuro del tiempo: bihar euria egingo du (mañana lloverá), eguraldi ona egingo du.": "Weather in the future: bihar euria egingo du (tomorrow it will rain), eguraldi ona egingo du.",
  "Hogei gradu daude = hay veinte grados (grados en singular tras el número, verbo plural).": "Hogei gradu daude = it is twenty degrees (degree singular after the number, plural verb).",
  "Invitar: nahi duzu etorri? (¿quieres venir?). En preguntas informales el verbo puede ir detrás.": "Inviting: nahi duzu etorri? (do you want to come?). In informal questions the verb can go after.",
  "ezin dut = no puedo; ezin naiz joan = no puedo ir. Ezin va delante del auxiliar.": "ezin dut = I can't; ezin naiz joan = I can't go. Ezin goes before the auxiliary.",
  "behar dut = tengo que: lan egin behar dut (tengo que trabajar).": "behar dut = I have to: lan egin behar dut (I have to work).",
  "Zer ordutan / non geratzen gara? = ¿a qué hora / dónde quedamos?": "Zer ordutan / non geratzen gara? = what time / where shall we meet?",
  "Me duele X: X-ko mina dut: buruko mina dut (dolor de cabeza), eztarriko mina, bizkarreko mina.": "X hurts: X-ko mina dut: buruko mina dut (headache), eztarriko mina, bizkarreko mina.",
  "gaixorik nago = estoy enfermo/a (con egon, como los estados). Hobeto nago = estoy mejor.": "gaixorik nago = I am ill (with egon, like states). Hobeto nago = I am better.",
  "Sentirse: ondo / gaizki sentitzen naiz. Nola sentitzen zara? = ¿cómo te sientes?": "Feeling: ondo / gaizki sentitzen naiz. Nola sentitzen zara? = how do you feel?",
  "Tener fiebre / resfriado: sukarra dut, hotzeria dut (con ukan, como «tener»).": "Having a fever / a cold: sukarra dut, hotzeria dut (with ukan, like “have”).",
  "El tiempo: ari du, egiten du, dago": "The weather: ari du, egiten du, dago",
  "Lo que cae ahora mismo va con ari du: euria ari du, elurra ari du. Lo que «hace» va con egiten du: hotz egiten du, bero egiten du, eguraldi ona egiten du. Lo que hay o cómo está el cielo, con dago: eguzkia dago, lainotuta dago. El viento anda: haizea dabil. Futuro: egingo du.": "What is falling right now goes with ari du: euria ari du, elurra ari du. What it “makes” goes with egiten du: hotz egiten du, bero egiten du, eguraldi ona egiten du. What there is or how the sky is, with dago: eguzkia dago, lainotuta dago. The wind walks: haizea dabil. Future: egingo du.",
