  "Entonces erais jóvenes.": "Then you were young.",
  "¿Qué hora era?": "What time was it?",
  "Era, fui: nintzen, zinen, zen": "Was: nintzen, zinen, zen",
  "El pasado de izan: ni nintzen, zu zinen, hura zen, gu ginen, zuek zineten, haiek ziren. Txikitan lotsatia nintzen (de pequeño era tímido).": "The past of izan: ni nintzen, zu zinen, hura zen, gu ginen, zuek zineten, haiek ziren. Txikitan lotsatia nintzen (as a child I was shy).",
  "Estaba: nengoen, zeunden, zegoen": "Was (state): nengoen, zeunden, zegoen",
  "El pasado de egon: ni nengoen, zu zeunden, hura zegoen, gu geunden, zuek zeundeten, haiek zeuden. Atzo etxean nengoen (ayer estaba en casa).": "The past of egon: ni nengoen, zu zeunden, hura zegoen, gu geunden, zuek zeundeten, haiek zeuden. Atzo etxean nengoen (yesterday I was at home).",
  "Cuándo: atzo, lehen, txikitan": "When: atzo, lehen, txikitan",
  "atzo (ayer), herenegun (anteayer), joan den astean (la semana pasada), iaz (el año pasado), lehen (antes), txikitan (de pequeño), orduan (entonces).": "atzo (yesterday), herenegun (the day before yesterday), joan den astean (last week), iaz (last year), lehen (before), txikitan (as a child), orduan (then).",
  "¡Mira esta foto! ¿Quién es?": "Look at this photo! Who is it?",
  "Soy yo, de pequeña. Era muy tímida.": "It's me, as a child. I was very shy.",
  "¿Y dónde estabas? ¿En la playa?": "And where were you? At the beach?",
  "Sí, en Zarautz. En verano siempre estábamos allí.": "Yes, in Zarautz. In summer we were always there.",
  "Nuen, zenuen, zuen · nituen": "Nuen, zenuen, zuen · nituen",
  "Eskola garaiaz hizketan · hablando de la época del colegio": "Eskola garaiaz hizketan · talking about school days",
  "Txikitan ___ nuen": "Txikitan ___ nuen",
  "yo tenía (una cosa)": "I had (one thing)",
  "tú tenías": "you had",
  "él/ella tenía": "he/she had",
  "nosotros teníamos": "we had",
  "vosotros teníais": "you (pl.) had",
  "ellos tenían": "they had",
  "yo tenía (varias)": "I had (several)",
  "tú tenías (varias)": "you had (several)",
  "él/ella tenía (varias)": "he/she had (several)",
  "nosotros teníamos (varias)": "we had (several)",
  "un perro": "a dog",
  "una bici": "a bike",
  "muchos amigos": "many friends",
  "mucho trabajo": "a lot of work",
  "tiempo (duración)": "time (duration)",
  "ganas": "desire, feeling like",
  "De pequeño/a tenía un perro.": "As a child I had a dog.",
  "Ayer tenía mucho trabajo.": "Yesterday I had a lot of work.",
  "¿Antes tenías una bici?": "Did you have a bike before?",
  "Mi abuelo tenía un caserío.": "My grandfather had a farmhouse.",
  "El año pasado no teníamos coche.": "Last year we didn't have a car.",
  "De pequeño/a tenía muchos amigos.": "As a child I had many friends.",
  "No tenía tiempo.": "I didn't have time.",
  "Tenía ganas, pero no podía.": "I felt like it, but I couldn't.",
  "¿Cuántos años tenías?": "How old were you?",
  "Tenía diez años.": "I was ten years old.",
  "Ellos tenían una casa grande.": "They had a big house.",
  "No teníamos dinero, pero estábamos contentos.": "We had no money, but we were happy.",
  "Tenía: nuen, zenuen, zuen": "Had: nuen, zenuen, zuen",
  "El pasado de ukan con una cosa: nik nuen, zuk zenuen, hark zuen, guk genuen, zuek zenuten, haiek zuten. Txakur bat nuen.": "The past of ukan with one thing: nik nuen, zuk zenuen, hark zuen, guk genuen, zuek zenuten, haiek zuten. Txakur bat nuen.",
  "Varias cosas: nituen": "Several things: nituen",
  "Como en presente (dut / ditut), el plural cambia el verbo: nituen, zenituen, zituen, genituen, zenituzten, zituzten. Lagun asko nituen, hamar urte nituen.": "As in the present (dut / ditut), the plural changes the verb: nituen, zenituen, zituen, genituen, zenituzten, zituzten. Lagun asko nituen, hamar urte nituen.",
  "No tenía: ez nuen …-rik": "Didn't have: ez nuen …-rik",
  "Ez nuen denborarik (no tenía tiempo), ez genuen autorik. El -rik de las negaciones también en pasado.": "Ez nuen denborarik (I didn't have time), ez genuen autorik. The -rik of negatives applies in the past too.",
  "¿Cómo eras de pequeño?": "What were you like as a child?",
  "¡Muy travieso! Tenía muchos amigos y un perro.": "Very naughty! I had many friends and a dog.",
  "¿Y tenías bici?": "And did you have a bike?",
  "No, no tenía bici. Pero no me importaba.": "No, I didn't have a bike. But I didn't mind.",
  "Mendira joan nintzen, film bat ikusi nuen": "Mendira joan nintzen, film bat ikusi nuen",
  "Astelehen goizean lanean · lunes por la mañana en el trabajo": "Astelehen goizean lanean · Monday morning at work",
  "___ nintzen · ___ nuen": "___ nintzen · ___ nuen",
  "fui": "I went",
  "estuve": "I was (somewhere)",
  "me quedé": "I stayed",
  "vi": "I saw",
  "comí": "I ate",
  "bebí": "I drank",
  "compré": "I bought",
  "hice": "I did",
  "leí": "I read",
  "comimos": "we had lunch",
  "cenamos": "we had dinner",
  "lo pasamos bien": "we had a good time",
  "¿Qué hiciste?": "What did you do?",
  "¿Adónde fuiste?": "Where did you go?",
  "Nada": "Nothing",
  "primero": "first",
  "después, luego": "then, afterwards",
  "al final": "in the end",
  "¿Qué hiciste el fin de semana?": "What did you do at the weekend?",
  "El sábado fui al monte.": "On Saturday I went to the mountains.",
  "Vi una película.": "I watched a film.",
  "Comimos con amigos.": "We had lunch with friends.",
  "El domingo me quedé en casa.": "On Sunday I stayed at home.",
  "Leí un libro.": "I read a book.",
  "Ane vino a cenar.": "Ane came for dinner.",
  "Lo pasamos muy bien.": "We had a very good time.",
  "Nada. ¡Dormí!": "Nothing. I slept!",
  "Primero fuimos a la playa y luego cenamos.": "First we went to the beach and then we had dinner.",
  "Al final me acosté tarde.": "In the end I went to bed late.",
  "Fui, vi: verbo + nintzen / nuen": "Went, saw: verb + nintzen / nuen",
  "Lo que pasó y terminó: el verbo en su forma básica + el auxiliar en pasado. Sin objeto, izan: joan nintzen, etorri zen, geratu ginen. Con objeto, ukan: ikusi nuen, jan nuen, bazkaldu genuen.": "What happened and is over: the verb in its basic form + the auxiliary in the past. Without an object, izan: joan nintzen, etorri zen, geratu ginen. With an object, ukan: ikusi nuen, jan nuen, bazkaldu genuen.",
  "Las tres formas del verbo": "The three forms of the verb",
  "joan (ir): joaten naiz (voy, habitual), joango naiz (iré), joan nintzen (fui). ikusi (ver): ikusten dut, ikusiko dut, ikusi nuen. La raíz manda; el auxiliar dice cuándo.": "joan (go): joaten naiz (I go, habitual), joango naiz (I will go), joan nintzen (I went). ikusi (see): ikusten dut, ikusiko dut, ikusi nuen. The stem stays; the auxiliary says when.",
  "Contar en orden": "Telling in order",
  "lehenengo (primero), gero (luego), eta gero (y luego), azkenean (al final). Zer egin zenuen? Nora joan zinen? son las preguntas del lunes.": "lehenengo (first), gero (then), eta gero (and then), azkenean (in the end). Zer egin zenuen? Nora joan zinen? are the Monday questions.",
  "¡Buenos días! ¿Qué hiciste el fin de semana?": "Good morning! What did you do at the weekend?",
  "El sábado fui al monte con amigos, y luego cenamos.": "On Saturday I went to the mountains with friends, and then we had dinner.",
  "¿Y el domingo?": "And on Sunday?",
  "Nada. Me quedé en casa y vi una película. ¿Y tú?": "Nothing. I stayed at home and watched a film. And you?",
  "Yo trabajé. ¡Qué pena!": "I worked. What a pity!",
  "Araba, Bizkaia, Gipuzkoa, Nafarroa, Lapurdi… Aste Nagusia, Olentzero": "Araba, Bizkaia, Gipuzkoa, Nafarroa, Lapurdi… Aste Nagusia, Olentzero",
  "Jaietan · en fiestas": "Jaietan · at the festivals",
  "___ ___ko hiriburua da": "___ ___ko hiriburua da",
  "el País Vasco (las siete provincias)": "the Basque Country (the seven provinces)",
  "Álava": "Álava",
  "Bizkaia": "Biscay",
  "Gipuzkoa": "Gipuzkoa",
  "Navarra": "Navarre",
