  "Empezar a: -tzen hasi": "To start doing: -tzen hasi",
  "hasi (empezar) y bukatu (terminar) van con el verbo en -tzen: euskara ikasten hasi nintzen, lanean hasi naiz. hasi es como joan: hasi naiz, hasi nintzen (sin objeto).": "hasi (to start) and bukatu (to finish) take the verb in -tzen: euskara ikasten hasi nintzen, lanean hasi naiz. hasi works like joan: hasi naiz, hasi nintzen (no object).",
  "Saber hacer: -tzen jakin": "To know how to: -tzen jakin",
  "badakit igeri egiten (sé nadar), ez dakit gidatzen (no sé conducir), badakizu dantzatzen? El pasado de dakit es nekien: lehen ez nekien.": "badakit igeri egiten (I can swim), ez dakit gidatzen (I can't drive), badakizu dantzatzen? The past of dakit is nekien: lehen ez nekien.",
  "Hace dos años: duela bi urte": "Two years ago: duela bi urte",
  "duela + tiempo = hace: duela bi urte (hace dos años), duela hilabete bat (hace un mes), duela aste bat (hace una semana).": "duela + time = ago: duela bi urte (two years ago), duela hilabete bat (a month ago), duela aste bat (a week ago).",
  "Hace dos años. Antes no sabía nada; ahora sé un poco.": "Two years ago. Before, I knew nothing; now I know a little.",
