  "No, eso no sé… ¡todavía!": "No, that I can't… yet!",
  "Había: zegoen (una cosa), zeuden (varias). Lantegi bat zegoen, denda asko zeuden. Es el pasado de dago / daude.": "There was: zegoen (one thing), zeuden (several). Lantegi bat zegoen, denda asko zeuden. It is the past of dago / daude.",
  "No había: ez zegoen + cosa con -rik: ez zegoen supermerkaturik, ez zegoen elektrizitaterik.": "There wasn't: ez zegoen + thing with -rik: ez zegoen supermerkaturik, ez zegoen elektrizitaterik.",
  "garai hartan = en aquella época. Va con el pasado: garai hartan lantegi bat zegoen.": "garai hartan = at that time. It goes with the past: garai hartan lantegi bat zegoen.",
  "aspaldi = hace mucho tiempo. Aspaldi iritsi zen (llegó hace mucho). Aspaldiko! = ¡cuánto tiempo!": "aspaldi = a long time ago. Aspaldi iritsi zen (it arrived long ago). Aspaldiko! = long time no see!",
  "Más: -ago. txikiagoa (más pequeño), lasaiagoa (más tranquilo). En plural -agoak: kaleak lasaiagoak ziren.": "More: -ago. txikiagoa (smaller), lasaiagoa (quieter). In the plural -agoak: kaleak lasaiagoak ziren.",
  "Pasado habitual sin objeto: -tzen + nintzen: jolasten nintzen (jugaba), joaten ginen (íbamos), jaikitzen ziren (se levantaban).": "Habitual past without object: -tzen + nintzen: jolasten nintzen (I played), joaten ginen (we went), jaikitzen ziren (they got up).",
  "Pasado habitual con objeto: -tzen + nuen: ikusten nuen (veía), jaten genuen (comíamos), egiten zuen (hacía).": "Habitual past with object: -tzen + nuen: ikusten nuen (I watched), jaten genuen (we ate), egiten zuen (he/she made).",
  "Pasado habitual con varias cosas: -tzen + nituen: marrazki bizidunak ikusten nituen, ipuinak kontatzen zituen.": "Habitual past with several things: -tzen + nituen: marrazki bizidunak ikusten nituen, ipuinak kontatzen zituen.",
  "Nunca: ez + auxiliar + inoiz + verbo: ez nuen inoiz barazkirik jaten (nunca comía verdura). La cosa negada lleva -rik.": "Never: ez + auxiliary + inoiz + verb: ez nuen inoiz barazkirik jaten (I never ate vegetables). The negated thing takes -rik.",
  "zitzaidan = me gustaba (una cosa). Pasado de zait: musika gustatzen zitzaidan. Para «te gustaba», zitzaizun; «le gustaba», zitzaion.": "zitzaidan = I liked (one thing). Past of zait: musika gustatzen zitzaidan. \"You liked\": zitzaizun; \"he/she liked\": zitzaion.",
  "zitzaizkidan = me gustaban (varias). Pasado de zaizkit, con -zki-: azterketak ez zitzaizkidan gustatzen.": "zitzaizkidan = I liked (several). Past of zaizkit, with -zki-: azterketak ez zitzaizkidan gustatzen.",
  "zitzaizun = te gustaba. Zein ikasgai gustatzen zitzaizun? (¿qué asignatura te gustaba?)": "zitzaizun = you liked. Zein ikasgai gustatzen zitzaizun? (which subject did you like?)",
  "gehien = lo que más. Va al final: jolastordua gustatzen zitzaidan gehien. Lo que menos: gutxien.": "gehien = most of all. It goes at the end: jolastordua gustatzen zitzaidan gehien. Least: gutxien.",
  "Estaba haciendo: ari + pasado de izan: lanean ari zen (estaba trabajando), ari ziren (estaban). Presente: ari naiz.": "Was doing: ari + past of izan: lanean ari zen (was working), ari ziren (were). Present: ari naiz.",
  "Empezar / terminar a hacer algo: verbo en -tzen + hasi / bukatu: euskara ikasten hasi nintzen, lanean hasi naiz.": "To start / finish doing something: verb in -tzen + hasi / bukatu: euskara ikasten hasi nintzen, lanean hasi naiz.",
  "Saber hacer: -tzen + jakin: badakit igeri egiten (sé nadar), ez dakit gidatzen. Pasado: ez nekien (no sabía).": "To know how to: -tzen + jakin: badakit igeri egiten (I can swim), ez dakit gidatzen. Past: ez nekien (I didn't know).",
  "nekien = sabía (pasado de dakit). Lehen ez nekien euskaraz (antes no sabía euskera). Tú: zenekien; él/ella: zekien.": "nekien = I knew (past of dakit). Lehen ez nekien euskaraz (before I didn't know Basque). You: zenekien; he/she: zekien.",
  "duela + tiempo = hace: duela bi urte (hace dos años), duela aste bat (hace una semana). Va con el pasado: duela bi urte hasi nintzen.": "duela + time = ago: duela bi urte (two years ago), duela aste bat (a week ago). It goes with the past: duela bi urte hasi nintzen.",
  "El verbo como nombre lleva -t(z)ea: irakurtzea gustatzen zait (me gusta leer), mendira joatea nahi dut.": "The verb as a noun takes -t(z)ea: irakurtzea gustatzen zait (I like reading), mendira joatea nahi dut.",
  "Pasado habitual: lo que hacía": "Habitual past: what I used to do",
  "Lo que hacías habitualmente en el pasado: verbo en -tzen / -ten + auxiliar en pasado. Sin objeto, izan: jolasten nintzen (jugaba), joaten ginen (íbamos). Con objeto, ukan: ikusten nuen (veía), egiten zuen (hacía); con varias cosas, nituen / zituen. Es el mismo esquema que el presente habitual (jolasten naiz, ikusten dut) con el auxiliar cambiado.": "What you did habitually in the past: verb in -tzen / -ten + auxiliary in the past. Without an object, izan: jolasten nintzen (I played), joaten ginen (we went). With an object, ukan: ikusten nuen (I watched), egiten zuen (he/she made); with several things, nituen / zituen. Same pattern as the habitual present (jolasten naiz, ikusten dut) with the auxiliary changed.",
  "presente habitual": "habitual present",
  "pasado habitual": "habitual past",
  "jolastu · jugar": "jolastu · to play",
  "irakurri · leer (varios)": "irakurri · to read (several)",
  "kontatu · contar (varios)": "kontatu · to tell (several)",
  "De pequeño/a jugaba en la calle.": "As a child I played in the street.",
  "La abuela hacía pan.": "Grandma made bread.",
  "En verano íbamos al caserío.": "In summer we went to the farmhouse.",
  "Ponlo en pasado y en «ellos»": "Put it in the past and in \"they\"",
  "Me gustaba: zitzaidan, zitzaizkidan": "I liked: zitzaidan, zitzaizkidan",
  "El pasado de gustatzen zait es gustatzen zitzaidan (me gustaba). Con varias cosas, zitzaizkidan (me gustaban). Las personas cambian como en presente: zitzaizun (te gustaba), zitzaion (le gustaba), zitzaigun (nos gustaba). Negativo: ez zitzaidan gustatzen.": "The past of gustatzen zait is gustatzen zitzaidan (I liked). With several things, zitzaizkidan. The persons change as in the present: zitzaizun (you liked), zitzaion (he/she liked), zitzaigun (we liked). Negative: ez zitzaidan gustatzen.",
  "presente (una)": "present (one)",
  "pasado (una)": "past (one)",
  "pasado (varias)": "past (several)",
  "a mí": "to me",
  "a ti": "to you",
