  "A la abuela le gustaban los cuentos.": "Grandma liked stories.",
  "Ahora son los exámenes (plural)": "Now it's the exams (plural)",
  "Añade «lo que más»": "Add \"most of all\"",
  "Había: zegoen, zeuden, ez zegoen …-rik": "There was: zegoen, zeuden, ez zegoen …-rik",
  "Para «había» se usa el pasado de egon: zegoen (una cosa), zeuden (varias). Preguntar: bazegoen …-rik? Afirmar con énfasis: bai, bazegoen. Negar: ez zegoen …-rik. Igual que en presente (dago / daude / ez dago …-rik) pero en pasado. Con garai hartan, lehen, aspaldi.": "For \"there was\" use the past of egon: zegoen (one thing), zeuden (several). Asking: bazegoen …-rik? Emphatic yes: bai, bazegoen. Negating: ez zegoen …-rik. Same as the present (dago / daude / ez dago …-rik) but in the past. With garai hartan, lehen, aspaldi.",
  "presente": "present",
  "hay / había (una)": "there is / was (one)",
  "hay / había (varias)": "there are / were (several)",
  "¿hay? / ¿había?": "is / was there?",
  "sí hay / sí había": "yes there is / was",
  "no hay / no había": "there isn't / wasn't",
  "¿Había mercado? Sí, lo había.": "Was there a market? Yes, there was.",
  "Ahora son muchas": "Now there are many",
  "Pregunta si había": "Ask whether there was",
  "Ponlo en pasado con «lehen»": "Put it in the past with \"lehen\"",
  "Empezar a, terminar de, saber hacer": "To start, to finish, to know how to",
  "Con hasi (empezar), bukatu (terminar) y jakin (saber) el otro verbo va en -tzen / -ten: ikasten hasi nintzen, lanean hasi naiz, igeri egiten badakit, ez dakit gidatzen. hasi y bukatu se conjugan con izan (hasi naiz, hasi nintzen) porque no llevan objeto. jakin: dakit, dakizu, daki; en pasado nekien, zenekien, zekien. ba- delante afirma: badakit.": "With hasi (to start), bukatu (to finish) and jakin (to know) the other verb goes in -tzen / -ten: ikasten hasi nintzen, lanean hasi naiz, igeri egiten badakit, ez dakit gidatzen. hasi and bukatu take izan (hasi naiz, hasi nintzen) because they have no object. jakin: dakit, dakizu, daki; past nekien, zenekien, zekien. ba- in front affirms: badakit.",
  "forma": "form",
