  "¡Felicidades y por muchos años!": "Happy birthday and many happy returns!",
  "Dar algo a alguien: dit, dizut, diot": "Giving something to someone: dit, dizut, diot",
  "Cuando hay tres participantes (quién, qué y a quién), el auxiliar los junta: eman dit (me ha dado), eman dizut (te he dado), eman diot (le he dado), eman digu (nos ha dado). Es el nor-nori-nork.": "When there are three participants (who, what and to whom), the auxiliary combines them: eman dit (he/she gave me), eman dizut (I gave you), eman diot (I gave him/her), eman digu (he/she gave us). This is nor-nori-nork.",
  "A quién: -ri": "To whom: -ri",
  "El que recibe lleva -ri: Aneri, amari, lagunari. Con pronombres: niri, zuri, hari, guri, zuei, haiei. Amari eman diot (se lo he dado a mamá).": "The receiver takes -ri: Aneri, amari, lagunari. With pronouns: niri, zuri, hari, guri, zuei, haiei. Amari eman diot (I gave it to mum).",
  "Varias cosas: dizki-": "Several things: dizki-",
  "Si lo que das es plural, aparece -zki-: lore batzuk eman dizkiot, liburuak ekarri dizkizut.": "If what you give is plural, -zki- appears: lore batzuk eman dizkiot, liburuak ekarri dizkizut.",
