  "didazu = tú a mí: utziko didazu? (¿me dejas?), emango didazu? (¿me das?). Y al revés, yo a ti: dizut: itzuliko dizut (te lo devolveré).": "didazu = you to me: utziko didazu? (will you lend me?), emango didazu? (will you give me?). And the other way, me to you: dizut: itzuliko dizut (I'll give it back to you).",
  "Devolver algo a alguien: itzuli": "Giving something back: itzuli",
