  "Quién a quién": "Who to whom",
  "Mirenek esan dit: Miren (con -k, hace) a mí (dit). Nik Mireni esan diot: yo (nik) a Miren (-i, diot). El -k marca quién lo hace; el -ri, quién lo recibe.": "Mirenek esan dit: Miren (with -k, the doer) to me (dit). Nik Mireni esan diot: I (nik) to Miren (-i, diot). The -k marks who does it; the -ri, who receives it.",
