  "Órdenes: el verbo tal cual": "Orders: the bare verb",
  "Para dar una orden a «tú» (zu) basta el verbo en su forma básica: hartu! (coge), moztu! (corta), itxaron! (espera). Sin auxiliar. El objeto va donde siempre: patatak moztu, o moztu patatak.": "To give an order to \"you\" (zu) the basic verb form is enough: hartu! (take), moztu! (cut), itxaron! (wait). No auxiliary. The object goes where it always does: patatak moztu, or moztu patatak.",
  "Primero, después, por último": "First, then, finally",
  "Para ordenar los pasos: lehenengo (primero), ondoren / gero (después), azkenik (por último), bitartean (mientras tanto).": "To order the steps: lehenengo (first), ondoren / gero (then), azkenik (finally), bitartean (meanwhile).",
  "No hagas: ez + verbo": "Don't: ez + verb",
  "La orden negativa es ez + verbo básico: ez erre (no quemes), ez bota (no eches), ez ahaztu gatza (no olvides la sal).": "The negative order is ez + basic verb: ez erre (don't burn), ez bota (don't pour), ez ahaztu gatza (don't forget the salt).",
  "¿Cómo se hace la tortilla de patata?": "How do you make a potato omelette?",
