  "Sino: baizik": "But rather: baizik",
  "Para corregir: ez X, Y baizik (no X, sino Y). Ez hartu lehenengo kalea, bigarrena baizik. baizik va al final.": "To correct: ez X, Y baizik (not X, but Y). Ez hartu lehenengo kalea, bigarrena baizik. baizik goes at the end.",
