  "Es mejor que: hobe duzu + verbo": "You'd better: hobe duzu + verb",
  "hobe duzu + verbo en forma básica: hobe duzu atseden hartu (mejor que descanses), hobe duzu joan (mejor que vayas). Para él/ella: hobe du; para mí: hobe dut.": "hobe duzu + basic verb: hobe duzu atseden hartu (you'd better rest), hobe duzu joan (you'd better go). For him/her: hobe du; for me: hobe dut.",
  "Tienes que: behar duzu": "You have to: behar duzu",
  "verbo + behar duzu: lo egin behar duzu. Negativo: ez duzu … behar: ez duzu hainbeste lan egin behar (no tienes que trabajar tanto).": "verb + behar duzu: lo egin behar duzu. Negative: ez duzu … behar: ez duzu hainbeste lan egin behar (you don't have to work so much).",
  "No te preocupes: ez kezkatu": "Don't worry: ez kezkatu",
