  "Quiero enviar este paquete a Francia.": "I want to send this parcel to France.",
  "¿Cuánto cuesta el sello?": "How much is the stamp?",
  "Recibirás el paquete mañana.": "You'll receive the parcel tomorrow.",
  "Coge turno y espere, por favor.": "Take a ticket and wait, please.",
  "No puedo venir hoy; ¿puedo venir mañana?": "I can't come today; can I come tomorrow?",
  "Puedo: dezaket": "I can: dezaket",
  "Para «poder» con un objeto (sacar dinero, hacer una transferencia): verbo en raíz + dezaket (yo), dezakezu (tú), dezake (él/ella). Dirua atera dezaket? (¿puedo sacar dinero?).": "For \"can\" with an object (withdraw money, make a transfer): verb stem + dezaket (I), dezakezu (you), dezake (he/she). Dirua atera dezaket? (can I withdraw money?).",
  "La raíz del verbo": "The verb stem",
  "En la forma cuidada, con -ke el verbo va en raíz: bidali → bidal dezaket, ikusi → ikus dezaket, konpondu → konpon dezakezu. En la calle se oye mucho también con el verbo entero (konpondu dezakezu, utzi dezaket); las dos se entienden y aquí verás ambas.": "In careful Basque, with -ke the verb takes its stem: bidali → bidal dezaket, ikusi → ikus dezaket, konpondu → konpon dezakezu. In everyday speech the full verb is also very common (konpondu dezakezu, utzi dezaket); both are understood and you'll see both here.",
  "El negativo sigue siendo el de siempre: ezin dut (no puedo), ezin dut gaur etorri. Y «puedo» también se dice ahal dut: etorri ahal naiz. dezaket es un poco más formal.": "The negative is still the usual one: ezin dut (I can't), ezin dut gaur etorri. And \"I can\" is also ahal dut: etorri ahal naiz. dezaket is a bit more formal.",
  "Buenos días. Quiero abrir una cuenta.": "Good morning. I want to open an account.",
  "Bien. ¿Ha traído el DNI? Tiene que rellenar este formulario.": "Fine. Have you brought your ID? You have to fill in this form.",
  "¿Puedo firmar aquí?": "Can I sign here?",
