  "Puedo venir: etor naiteke": "I can come: etor naiteke",
  "Con verbos sin objeto (venir, ir, quedarse) el potencial es naiteke (yo), zaitezke (tú), daiteke (él/ella), gaitezke (nosotros): etor naiteke? (¿puedo venir?), joan zaitezke (puedes ir).": "With verbs without an object (come, go, stay) the potential is naiteke (I), zaitezke (you), daiteke (he/she), gaitezke (we): etor naiteke? (can I come?), joan zaitezke (you can go).",
  "Raíz otra vez": "The stem again",
  "etorri → etor naiteke, joan → joan naiteke, geratu → gera naiteke, sartu → sar naiteke. Igual que con dezaket: se quita -i / -tu.": "etorri → etor naiteke, joan → joan naiteke, geratu → gera naiteke, sartu → sar naiteke. Same as with dezaket: drop -i / -tu.",
  "Para cuándo: noizko": "By when: noizko",
