  "Salir de: -tik": "Leaving from: -tik",
  "Zein nasatik? (¿de qué andén?), hirugarren nasatik (del tercer andén), geltokitik (de la estación). Y con hora: hamaiketan irteten da (sale a las once).": "Zein nasatik? (from which platform?), hirugarren nasatik (from platform three), geltokitik (from the station). And with a time: hamaiketan irteten da (it leaves at eleven).",
