  "Yo querría vivir más tranquilo/a, nada más.": "I would just like to live more peacefully, nothing else.",
  "Me gustaría: nahiko nuke": "I would like: nahiko nuke",
  "nahi dut (quiero) → nahiko nuke (querría, me gustaría). Es el condicional: nuke (yo), zenuke (tú), luke (él/ella), genuke (nosotros). Euskal Herrian bizi nahiko nuke.": "nahi dut (I want) → nahiko nuke (I would like). It's the conditional: nuke (I), zenuke (you), luke (he/she), genuke (we). Euskal Herrian bizi nahiko nuke.",
  "Haría, iría: -ko nuke, -ko nintzateke": "I would do, I would go: -ko nuke, -ko nintzateke",
  "Con objeto: verbo + -ko + nuke: erosiko nuke (compraría), ezagutuko nuke. Sin objeto: -ko + nintzateke: joango nintzateke (iría), biziko nintzateke (viviría).": "With an object: verb + -ko + nuke: erosiko nuke (I would buy), ezagutuko nuke. Without an object: -ko + nintzateke: joango nintzateke (I would go), biziko nintzateke (I would live).",
  "Me gustaría + verbo: litzaidake + -tzea": "I would like + verb: litzaidake + -tzea",
  "gustatuko litzaidake (me gustaría) + la acción con -tzea: gustatuko litzaidake euskaraz hitz egitea, bidaiatzea, lan berri bat aurkitzea.": "gustatuko litzaidake (I would like) + the action with -tzea: gustatuko litzaidake euskaraz hitz egitea, bidaiatzea, lan berri bat aurkitzea.",
