  "Nos gustaría invitaros.": "We would like to invite you.",
  "¿Vendrías a nuestra boda?": "Would you come to our wedding?",
  "Ponlo en condicional (iría)": "Put it in the conditional (I would go)",
  "Creo que, ha dicho que: -la": "I think that, he/she said that: -la",
  "Después de uste dut (creo), esan du (ha dicho), ziur nago (estoy seguro), badirudi (parece), iruditzen zait (me parece), gogoratu (recuerda) o badakit (sé), la frase subordinada lleva -la pegado al auxiliar: da → dela, du → duela, dago → dagoela, dira → direla, naiz → naizela, dut → dudala, dute → dutela, ditu → dituela, zen → zela, zuen → zuela. La subordinada va detrás: uste dut ona dela. Negativo de creer: ez dut uste (… -nik).": "After uste dut (I think), esan du (he/she said), ziur nago (I'm sure), badirudi (it seems), iruditzen zait (it seems to me), gogoratu (remember) or badakit (I know), the subordinate clause takes -la attached to the auxiliary: da → dela, du → duela, dago → dagoela, dira → direla, naiz → naizela, dut → dudala, dute → dutela, ditu → dituela, zen → zela, zuen → zuela. The clause goes after: uste dut ona dela. Negative of thinking: ez dut uste (… -nik).",
  "auxiliar": "auxiliary",
  "con -la": "with -la",
  "Dilo con «creo que»": "Say it with \"I think that\"",
  "Dilo con «estoy seguro de que»": "Say it with \"I'm sure that\"",
  "Dilo con «Miren ha dicho que»": "Say it with \"Miren said that\"",
  "Dilo con «mamá me ha dicho que»": "Say it with \"mum told me that\"",
  "Si…: la condición con ba-": "If…: the condition with ba-",
  "Para decir «si» se pega ba- al auxiliar (o al verbo sintético): egiten badu (si hace), badut (si tengo), bazaude (si estás), bada (si es), badator (si viene), badakizu (si sabes). La condición va primero, con coma, y el resultado detrás, normalmente en futuro (-ko): euria egiten badu, etxean geratuko naiz. Negativo: ez badator (si no viene), ez baduzu nahi. «Si no, de lo contrario»: bestela. Ojo: badago también puede ser «sí hay» (énfasis); el contexto lo aclara.": "To say \"if\", attach ba- to the auxiliary (or to the synthetic verb): egiten badu (if it does), badut (if I have), bazaude (if you are), bada (if it is), badator (if he/she comes), badakizu (if you know). The condition goes first, with a comma, and the result after, usually in the future (-ko): euria egiten badu, etxean geratuko naiz. Negative: ez badator (if he/she doesn't come), ez baduzu nahi. \"Otherwise\": bestela. Note: badago can also mean \"yes there is\" (emphasis); context makes it clear.",
  "auxiliar / verbo": "auxiliary / verb",
  "con ba- (si…)": "with ba- (if…)",
  "ez dator": "ez dator",
  "Si quieres, podemos ir a la cascada.": "If you want, we can go to the waterfall.",
  "Únelo con «si»": "Join them with \"if\"",
  "Ponlo en negativo (si no viene, empezaremos sin ella)": "Make it negative (if she doesn't come, we'll start without her)",
